const e=JSON.parse('{"key":"v-a567c442","path":"/Projects-docs/Interview/Liunx.html","title":"内核基础概念","lang":"zh-CN","frontmatter":{"description":"#Linux 内核基础概念 文件系统 树形结构 1、/bin：存放二进制可执行命令目录 /bin 目录包含了许多用户级的基本命令和程序。这些命令和程序对于系统启动和运行是必需的。例如，常见的命令如 ls, cp, mv, cat 等都存放在这个目录下。 2、/lib：存放标准程序设计库目录，又叫动态链接共享库目录 /lib 目录包含了系统运行时所需的基本共享库文件和内核模块。这些库文件被系统上的许多程序共享使用，类似于 Windows 中的 DLL 文件。","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/Projects-docs/Interview/Liunx.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"内核基础概念"}],["meta",{"property":"og:description","content":"#Linux 内核基础概念 文件系统 树形结构 1、/bin：存放二进制可执行命令目录 /bin 目录包含了许多用户级的基本命令和程序。这些命令和程序对于系统启动和运行是必需的。例如，常见的命令如 ls, cp, mv, cat 等都存放在这个目录下。 2、/lib：存放标准程序设计库目录，又叫动态链接共享库目录 /lib 目录包含了系统运行时所需的基本共享库文件和内核模块。这些库文件被系统上的许多程序共享使用，类似于 Windows 中的 DLL 文件。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2024-03-13T15:21:43.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2024-03-13T15:21:43.000Z"}]]},"headers":[{"level":3,"title":"文件系统","slug":"文件系统","link":"#文件系统","children":[]},{"level":3,"title":"进程、线程、cpu、mem查看","slug":"进程、线程、cpu、mem查看","link":"#进程、线程、cpu、mem查看","children":[]},{"level":3,"title":"了解系统调用，中断、内核态、用户态等概念","slug":"了解系统调用-中断、内核态、用户态等概念","link":"#了解系统调用-中断、内核态、用户态等概念","children":[]},{"level":3,"title":"内存管理","slug":"内存管理","link":"#内存管理","children":[]},{"level":3,"title":"Shell","slug":"shell","link":"#shell","children":[]},{"level":3,"title":"熟练使用grep、tail、top、ps、vim、curl等命令进行查看日志、问题排查、调试验证","slug":"熟练使用grep、tail、top、ps、vim、curl等命令进行查看日志、问题排查、调试验证","link":"#熟练使用grep、tail、top、ps、vim、curl等命令进行查看日志、问题排查、调试验证","children":[]},{"level":3,"title":"网络通信","slug":"网络通信","link":"#网络通信","children":[]},{"level":3,"title":"I/O多路复用","slug":"i-o多路复用","link":"#i-o多路复用","children":[]},{"level":3,"title":"HTTP协议","slug":"http协议","link":"#http协议","children":[]}],"git":{"createdTime":1710343303000,"updatedTime":1710343303000,"contributors":[{"name":"ClearDewy","email":"11166208+cleardewy@user.noreply.gitee.com","commits":1}]},"readingTime":{"minutes":23.6,"words":7080},"filePathRelative":"Projects-docs/Interview/Liunx.md","localizedDate":"2024年3月13日","excerpt":"<p>#Linux</p>\\n<h1> 内核基础概念</h1>\\n<h3> 文件系统</h3>\\n<h4> 树形结构</h4>\\n<h5> 1、/bin：存放二进制可执行命令目录</h5>\\n<p>/bin 目录包含了许多用户级的基本命令和程序。这些命令和程序对于系统启动和运行是必需的。例如，常见的命令如 ls, cp, mv, cat 等都存放在这个目录下。</p>\\n<h5> 2、/lib：存放标准程序设计库目录，又叫动态链接共享库目录</h5>\\n<p>/lib 目录包含了系统运行时所需的基本共享库文件和内核模块。这些库文件被系统上的许多程序共享使用，类似于 Windows 中的 DLL 文件。</p>","autoDesc":true}');export{e as data};
